using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Microsoft.Win32;
namespace Aurora {
public static class NextReleaseChecks {
    static Dictionary<string,object> Release(string tag,bool preview,bool draft=false){return new Dictionary<string,object>{{"tag_name",tag},{"name",tag},{"prerelease",preview},{"draft",draft},{"body","Notes"},{"html_url",OuOUpdates.Repository+"/releases/tag/"+tag},{"assets",new object[]{new Dictionary<string,object>{{"name","OuO-test.zip"},{"size",1234},{"digest","sha256:"+new string('a',64)},{"browser_download_url",OuOUpdates.Repository+"/releases/download/"+tag+"/OuO-test.zip"}}}}};}
    static bool Throws(Action action){try{action();return false;}catch{return true;}}
    public static void Run(Action<bool,string> check,string folder){
        check(new WorkProgress{Done=5,Total=20}.Percent==25,"actual counted operation progress");
        check(new WorkProgress{Done=1048576,Total=2097152,Bytes=true}.Label.Contains("50%")&&new WorkProgress{Done=1048576,Total=2097152,Bytes=true}.Label.Contains("MB"),"download progress uses readable units");check(new WorkProgress{Done=50,Total=10}.Percent==100,"progress never exceeds total");
        var dism=WorkReporting.FromToolLine("[======================42.5%                     ]","dism.exe");check(dism!=null&&Math.Abs(dism.Percent-42.5)<.01,"parse actual DISM progress");
        check(WorkReporting.FromToolLine("Data: 30%","cmd.exe")==null,"unrelated output is not invented progress");
        check(WorkReporting.FromToolLine("[ 140% ]","dism.exe")==null,"reject impossible tool progress");
        var reported=WorkReporting.FromToolLine("OUO-PROGRESS|2|3|Installing test","powershell.exe");check(reported!=null&&reported.Done==2&&reported.Total==3,"structured installer progress");
        var json=new JavaScriptSerializer().Serialize(new object[]{Release("v1.0.0.108",false),Release("v1.1.0.0-preview1",true),Release("v9.0.0",false,true)});
        check(OuOUpdates.Parse(json,false).Length==1,"stable channel excludes previews and drafts");
        check(OuOUpdates.Parse(json,true).First().Version==new Version(1,1,0,0),"release order uses numeric version");
        check(!OuOUpdates.TrustedDownload("https://github.com.evil.invalid/CarvalhoRonan/OuO/releases/download/a/b.zip"),"reject lookalike update host");
        check(!OuOUpdates.TrustedDownload("http://github.com/CarvalhoRonan/OuO/releases/download/a/b.zip"),"reject insecure update transport");
        check(!OuOUpdates.TrustedDownload("https://github.com/another/OuO/releases/download/a/b.zip"),"reject another update repository");
        var missingDigest=Release("v2.0.0",false);((Dictionary<string,object>)((object[])missingDigest["assets"])[0])["digest"]="";check(OuOUpdates.Parse(new JavaScriptSerializer().Serialize(new[]{missingDigest}),true).Length==0,"reject update without published hash");
        string fixture=Path.Combine(folder,"next-release");Directory.CreateDirectory(fixture);string zip=Path.Combine(fixture,"safe.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){using(var writer=new StreamWriter(z.CreateEntry("OuO-test/readme.txt").Open()))writer.Write("fixture");}string extracted=Path.Combine(fixture,"safe");Directory.CreateDirectory(extracted);OuOUpdates.Extract(zip,extracted,null,CancellationToken.None);check(File.ReadAllText(Path.Combine(extracted,"OuO-test","readme.txt"))=="fixture","update archive extracts contained files");
        string traversal=Path.Combine(fixture,"traversal.zip");using(var z=ZipFile.Open(traversal,ZipArchiveMode.Create)){z.CreateEntry("../escape.txt");}check(Throws(()=>OuOUpdates.Extract(traversal,extracted,null,CancellationToken.None))&&!File.Exists(Path.Combine(fixture,"escape.txt")),"reject update archive traversal before writes");
        string duplicate=Path.Combine(fixture,"duplicate.zip");using(var z=ZipFile.Open(duplicate,ZipArchiveMode.Create)){z.CreateEntry("App.txt");z.CreateEntry("app.txt");}check(Throws(()=>OuOUpdates.Extract(duplicate,extracted,null,CancellationToken.None)),"reject case-insensitive duplicate archive files");
        using(var cancellation=new CancellationTokenSource()){cancellation.Cancel();string canceled=Path.Combine(fixture,"cancel");Directory.CreateDirectory(canceled);check(Throws(()=>OuOUpdates.Extract(zip,canceled,null,cancellation.Token))&&!Directory.GetFiles(canceled,"*",SearchOption.AllDirectories).Any(),"cancel update extraction without starting a file");}
        string sensitive="Authorization: Bearer ABCDEF123\nrefresh_token=supersecret\nname@example.invalid\nC:\\Users\\Example\\private.txt\nS-1-5-21-123-456-789-1001";string cleaned=DiagnosticPrivacy.Clean(sensitive);check(!cleaned.Contains("ABCDEF123")&&!cleaned.Contains("supersecret")&&!cleaned.Contains("name@example.invalid")&&!cleaned.Contains("private.txt")&&!cleaned.Contains("S-1-5-21"),"remove credentials, email, paths and account ID from support report");
        var store=new MemoryRegistryStore();var journal=new Journal(Path.Combine(fixture,"journal"),store);store.Set("HKCU","Test","A",1,RegistryValueKind.DWord);store.Set("HKCU","Test","B",2,RegistryValueKind.DWord);
        Journal.SetOperation("one","Two settings");journal.RegistryChange("a","HKCU","Test","A",10,RegistryValueKind.DWord);journal.RegistryChange("b","HKCU","Test","B",20,RegistryValueKind.DWord);Journal.SetOperation(null,null);check(journal.ChangeGroups().Single().Count==2,"group related changes by operation");journal.UndoGroup("one");check((int)store.Read("HKCU","Test","A").Value==1&&(int)store.Read("HKCU","Test","B").Value==2,"restore all selected operation values");
        Journal.SetOperation("repeat","Repeated setting");journal.RegistryChange("a","HKCU","Test","A",3,RegistryValueKind.DWord);journal.RegistryChange("a","HKCU","Test","A",4,RegistryValueKind.DWord);Journal.SetOperation(null,null);journal.UndoGroup("repeat");check((int)store.Read("HKCU","Test","A").Value==1,"undo repeated writes in reverse order within an operation");
        Journal.SetOperation("external","External conflict");journal.RegistryChange("a","HKCU","Test","A",7,RegistryValueKind.DWord);journal.RegistryChange("b","HKCU","Test","B",8,RegistryValueKind.DWord);Journal.SetOperation(null,null);store.Set("HKCU","Test","A",999,RegistryValueKind.DWord);check(Throws(()=>journal.UndoGroup("external"))&&(int)store.Read("HKCU","Test","B").Value==8,"preflight all changes preserves other values on conflict");
        store.Set("HKCU","Test","A",7,RegistryValueKind.DWord);Journal.SetOperation("later","Newer change");journal.RegistryChange("a","HKCU","Test","A",11,RegistryValueKind.DWord);Journal.SetOperation(null,null);check(Throws(()=>journal.UndoGroup("external")),"refuse to overwrite a newer operation");journal.UndoGroup("later");journal.UndoGroup("external");check((int)store.Read("HKCU","Test","A").Value==1,"restore newer then older operations safely");
        var record=new OperationRecord{Id="fixture",Title="Fixture operation",Result="OK",Started=DateTime.UtcNow,Finished=DateTime.UtcNow,Before=new MaintenanceSample{At=DateTime.UtcNow,FreeDisk=100,FreeMemory=100},After=new MaintenanceSample{At=DateTime.UtcNow,FreeDisk=200,FreeMemory=200}};journal.SaveOperation(record);check(journal.OperationResults().Single().Summary.Contains("→"),"operation comparison persists across journal instances");
        var package=new DriverCleanupPackage{Inf="oem42.inf",Provider="NVIDIA",Signed=true};check(package.Eligible,"eligible OEM multimedia package");package.SharedOutsideScope=true;check(!package.Eligible,"block driver package shared with other device classes");package.SharedOutsideScope=false;package.Inf="../../windows.inf";check(!package.Eligible,"reject unbounded driver identifier");package.Inf="oem42.inf";package.Provider="Microsoft";check(!package.Eligible,"preserve inbox Microsoft drivers");package.Provider="Realtek";package.Signed=false;check(!package.Eligible,"refuse unverified driver cleanup package");
        check(DiskManufacturer.Support("","Unknown Model")==null,"unknown disk brand does not invent a support site");check(DiskManufacturer.Support("Samsung","test").StartsWith("https://semiconductor.samsung.com/"),"known disk maps to official vendor domain");
        check(DailyMaintenance.Time("00:00")=="00:00"&&DailyMaintenance.Time("23:59")=="23:59"&&Throws(()=>DailyMaintenance.Time("24:00")),"time picker preserves exact 24-hour scheduler bounds");
        var panel=new CardColumns{MaxColumns=2};var a=new Border{Height=100};var b=new Border{Height=150};var c=new Border{Height=30};panel.Children.Add(a);panel.Children.Add(b);panel.Children.Add(c);panel.Measure(new Size(900,Double.PositiveInfinity));panel.Arrange(new Rect(0,0,900,panel.DesiredSize.Height));check(VisualTreeHelper.GetOffset(a).Y==VisualTreeHelper.GetOffset(b).Y&&VisualTreeHelper.GetOffset(c).Y==162,"cards align by rows instead of shortest column");panel.IndependentColumns=true;panel.Measure(new Size(900,Double.PositiveInfinity));panel.Arrange(new Rect(0,0,900,panel.DesiredSize.Height));check(VisualTreeHelper.GetOffset(c).Y==112,"independent form columns avoid full-row gaps without moving cards to another group");panel.Measure(new Size(240,Double.PositiveInfinity));panel.Arrange(new Rect(0,0,240,panel.DesiredSize.Height));check(a.ActualWidth<=240&&c.ActualWidth<=240,"cards fit a narrow content area");
        check(BrowserExtensions.MergeChromium(null,"chromium",true,false).Contains(BrowserExtensions.ChromeUblock),"Chromium receives the compatible extension policy");var manual=BrowserExtensions.Apply(new[]{new BrowserInfo{Id="vivaldi",Name="Vivaldi",Family="chromium",Installed=true}},true,false,new MemoryRegistryStore(),new Journal(Path.Combine(fixture,"manual"),new MemoryRegistryStore()));check(manual.Contains(L.T("assistida","guided")),"unvalidated browser automation uses the official-store fallback");
    }
}
}
